  private readonly Dictionary<int,Sprite> iceChapterSprites=new Dictionary<int,Sprite>();
  private Sprite IceChapterSprite(int index){Sprite s;if(iceChapterSprites.TryGetValue(index,out s)&&s!=null)return s;var t=Resources.Load<Texture2D>("NakiArt/IceChapter/creatures");if(t==null)return IceSprite(index<2?0:2);t.filterMode=FilterMode.Point;float[] left={0,.20f,.42f,.72f},right={.20f,.42f,.72f,1};Rect rect=new Rect(t.width*left[index],0,t.width*(right[index]-left[index]),t.height);s=Sprite.Create(t,rect,new Vector2(.5f,.12f),t.height/(index<2?1.35f:3.2f),0,SpriteMeshType.FullRect);ownedAssets.Add(s);iceChapterSprites[index]=s;return s;}
  private void LoadIceChapterArt(){for(int i=0;i<4;i++){var frames=new Sprite[16];for(int k=0;k<16;k++)frames[k]=IceChapterSprite(i);enemyActionArt[(EnemyKind)((int)EnemyKind.SnowCrab+i)]=frames;}chapterEndingArt=Resources.Load<Texture2D>("NakiArt/IceChapter/tide-ending");var floor=Resources.Load<Texture2D>("NakiArt/IceChapter/floors");if(floor!=null){floor.filterMode=FilterMode.Point;for(int stage=1;stage<3;stage++){var tile=Sprite.Create(floor,new Rect((stage-1)*floor.width/2f,0,floor.width/2f,floor.height),Vector2.one*.5f,floor.width/8f,0,SpriteMeshType.FullRect);ownedAssets.Add(tile);chapterFloors[stage]=tile;}}}
  private void ExpandIceChapterGraph(){
   var old=chapterNames;chapterNames=new string[42];Array.Copy(old,chapterNames,5);
   Vector2Int[] extra={new Vector2Int(-1,0),new Vector2Int(-1,1),new Vector2Int(-1,-1),new Vector2Int(0,1),new Vector2Int(0,-1),new Vector2Int(2,1),new Vector2Int(2,-1),new Vector2Int(3,1),new Vector2Int(3,0)};
   string[] first={"冻潮巷","护灯队长","渔具仓","避风棚","旧船匠的工具","霜甲巡道","断桨营地","守灯补给站","临峡栈道"};
   for(int id=5;id<42;id++){int stage=id/14,local=id%14;Vector2Int cell=stage==0?extra[id-5]:new Vector2Int(local%5,local/5);RoomKind kind=local==0?RoomKind.Rest:local==12?RoomKind.Boss:local==4||local==10?RoomKind.Event:local==5||local==9?RoomKind.Elite:local==7?RoomKind.Reward:local==11||local==13?RoomKind.Rest:RoomKind.Combat;if(stage==0)kind=id==6?RoomKind.Elite:id==8||id==12||id==13?RoomKind.Rest:id==9?RoomKind.Reward:id==11?RoomKind.Event:RoomKind.Combat;var n=new RoomNode{id=id,stage=stage,floor=stage,cell=cell,halfWidth=8+(local%3)*.5f,halfHeight=4.8f+(local%2)*.3f,kind=kind,waves=kind==RoomKind.Elite?4:2+stage,stairsTo=-1,depth=8+stage*3,layout=local};journeyRooms.Add(n);chapterNames[id]=stage==0?first[id-5]:(stage==1?new[]{"峡口营地","裂潮长桥","雪壳滩","风雪裂隙","受困破冰队","霜纹执礼者","冰峡回廊","队员的装备箱","回声石道","护灯队长","绞盘观测站","镜前营火","霜镜巡狩者","晶庭石阶"}:new[]{"晶庭前哨","潮纹环廊","冰晶林","冻潮侧殿","西回流槽","冰甲禁卫","碎霜庭院","守灯遗藏","潮汐穹顶","晶纹执礼者","东回流槽","守望者前厅","寒潮守望者","回流闸室"})[local];}
   for(int a=0;a<42;a++)for(int b=a+1;b<42;b++)if(journeyRooms[a].stage==journeyRooms[b].stage&&(journeyRooms[a].cell-journeyRooms[b].cell).sqrMagnitude==1){if(!journeyRooms[a].links.Contains(b))journeyRooms[a].links.Add(b);if(!journeyRooms[b].links.Contains(a))journeyRooms[b].links.Add(a);}
   stageStarts[0]=0;stageStarts[1]=14;stageStarts[2]=28;stageEnds[0]=2;stageEnds[1]=26;stageEnds[2]=40;journeyRooms[2].stairsTo=14;journeyRooms[14].stairsTo=2;journeyRooms[26].stairsTo=28;journeyRooms[28].stairsTo=26;RebuildIceRoute();
  }
  private void MigrateIceChapter(ChapterCheckpoint s){if(s!=null&&s.island=="ice_sample"&&s.map=="ice-ch3-v1"&&s.rooms!=null&&s.rooms.Length==42){s.map="ice-ch3-v2";return;}if(s==null||s.island!="ice_sample"||s.rooms==null||(s.map!="ice-s1-v1"&&s.map!="ice-s2-v1"))return;int length=s.rooms.Length;if(length!=3&&length!=5)return;var rooms=new ChapterRoomState[42];Array.Copy(s.rooms,rooms,length);for(int i=length;i<42;i++)rooms[i]=new ChapterRoomState{weapons=Array.Empty<CheckpointWeapon>(),crystals=Array.Empty<CheckpointEssence>()};s.rooms=rooms;s.map="ice-ch3-v2";s.stone=s.ending=s.cgPending=false;s.west=s.east=s.ranger=s.lampCarried=s.lampGiven=false;}
  private void BuildIceChapterCover(RoomNode n){iceFissures.Clear();if(n.kind==RoomKind.Rest||n.kind==RoomKind.Event||n.kind==RoomKind.Reward)return;int variant=(n.layout+activeSeed)%3;foreach(Vector2 at in variant==0?new[]{new Vector2(-4,2),new Vector2(4,-2)}:variant==1?new[]{new Vector2(-4,-2),new Vector2(4,2),new Vector2(0,2.5f)}:new[]{new Vector2(-4,1.5f),new Vector2(4,1.5f),new Vector2(0,-2)})AddIceObstacle(n.stage==1?6:n.stage==2?5:3,at);}
  private void SpawnIceChapterWave(RoomNode n){if(n.kind==RoomKind.Boss){SpawnJourneyEnemy(n.stage==0?EnemyKind.IceBeast:n.stage==1?EnemyKind.FrostMirror:EnemyKind.TideGuardian,Vector2.zero,n.depth);return;}var rng=new System.Random(activeSeed+n.id*301+currentWave*97);int count=Mathf.Min(7,4+n.stage+(currentWave>=3?1:0));int ranged=0;EnemyKind[] kinds=n.stage==0?new[]{EnemyKind.IceGuard,EnemyKind.IceWisp,EnemyKind.FrostHound,EnemyKind.IceArcher}:new[]{EnemyKind.IceGuard,EnemyKind.FrostHound,EnemyKind.IceArcher,EnemyKind.IceRunecaster,EnemyKind.SnowCrab,EnemyKind.SnowMoth};for(int i=0;i<count;i++){EnemyKind k=i==0?EnemyKind.FrostHound:i==1?EnemyKind.IceArcher:n.stage>0&&i==2?EnemyKind.IceRunecaster:kinds[rng.Next(kinds.Length)];bool range=k==EnemyKind.IceWisp||k==EnemyKind.IceArcher||k==EnemyKind.IceRunecaster;if(range&&ranged++>=(n.stage==0?2:3))k=EnemyKind.FrostHound;QueueEnemy(k,FindJourneySpawn(rng,.5f),n.kind==RoomKind.Elite&&i==0);pendingSpawns[pendingSpawns.Count-1].when=clock+1.2f+i*.35f;}}
  private void IceChapterRest(RoomNode n,bool first){if(n.kind==RoomKind.Reward&&!n.lootSeeded)IceChapterRoomCleared(n);}
  private void IceChapterRoomCleared(RoomNode n){if(n.kind==RoomKind.Elite){DropIslandEliteReward(n);return;}if(n.lootSeeded||n.kind==RoomKind.Boss||n.kind==RoomKind.Reward)return;n.lootSeeded=true;if(n.kind==RoomKind.Combat||n.kind==RoomKind.Elite||n.kind==RoomKind.Reward){if(n.kind==RoomKind.Reward||n.kind==RoomKind.Elite)ChapterDrop(n.kind==RoomKind.Reward?14+n.stage%4:currentRoom%2==0?12:11,new Vector2(-2,.5f));var essence=new StoredEssence{at=FindFreeInteractionPoint(new Vector2(2,.5f)),value=20+n.stage*5,born=clock};n.essence.Add(essence);DrawEssence(essence);}}
  private void BuildIceChapterActions(RoomNode n){
   if(n.id==40&&!n.cleared){DrawBattleWinches();return;}if(!n.cleared)return;
   if(n.id==0&&chapterEnding)AddChapterAction(340,new Vector2(2.5f,.45f),"展开航图 · 推荐赤炉群岛");if(n.id==0){AddChapterAction(301,new Vector2(-3,1),"与守塔人交谈",IceSprite(3));HarborBoat(304,Vector2.zero,new Vector2(-1,.45f),"展开 Naki 航图 · 自选目的地",null);if(chapterStone&&chapterWest&&chapterEast&&chapterRanger&&chapterLampCarried)AddChapterAction(320,new Vector2(-3,2.4f),chapterEnding?"重温归航一刻":"点亮归航灯",IceSprite(5));}
   if(n.id==2){AddChapterAction(302,new Vector2(-3,2),"破冰队记录 · 学习冰法术",IceSprite(5));}
   if(n.id==18) {AddChapterAction(310,new Vector2(-3.8f,-.4f),chapterRanger?"获救的破冰队员":"转动营地绞盘 · 打开救援门");var person=Draw("Stranded expedition member",ResidentSprite(4),chapterRanger?new Vector2(-.4f,.2f):new Vector2(-2,1.2f),Vector2.one,Color.white,DepthAt(1.2f));person.transform.SetParent(chapterFocus.transform,true);IceCampWall(new Vector2(-3,1.35f),new Vector2(.12f,2));IceCampWall(new Vector2(-1,1.35f),new Vector2(.12f,2));IceCampWall(new Vector2(-2,2.3f),new Vector2(2,.12f));if(!chapterRanger)IceCampWall(new Vector2(-2,.4f),new Vector2(2,.12f));BuildIceRescueWinch();}
   // The objective chevron already guides rescue; no redundant wooden arrow board.
   if(n.id==41&&chapterStone)BuildIceSluiceRoom();
   BuildIceQuietRoom(n);
  }
  private void IceChapterAction(int a){
   if(a==340){OpenWorldAtlas(3);return;}if(a==330||a==331){ActivateBattleWinch(a-330);return;}if(a==304){OpenWorldAtlas(2);return;}
   if(a==301&&chapterEnding){TellStory("守塔人：潮声回来了，灯下的人也回来了。旧船单上的那位旅人，却一直没有归票。","守塔人递来封好的药单：若有机会去暮钟岛，替我们问问收药的人，为什么后来连回信也没有了。");return;}if(a==301)TellStory(chapterEnding?"守塔人：潮声回来了。灯下的人，也一个个回来了。":"守塔人：灯不能替他们破冰，至少能告诉他们，岸上还有人在等。","少年：我沿栈道去找，替你把他们带回来。");
   if(a==302&&currentRoom==2&&journeyRooms[2].cleared){if(iceSpikeKnown&&iceRingKnown){TellStory("你重新展开破冰队记录。冰峡的求救灯、殿下的潮纹，都沿着纸上的箭头连成了归途。");return;}iceSpikeKnown=iceRingKnown=true;AnnounceDiscovery("已领悟冰锥与霜环 · T 自选装备，保留当前技能");TellStory("记录：沿尖端生长的霜，是冰锥；让寒意向身外散开，便是护身的霜环。","记录末页指向裂潮冰峡。一支队伍，还在等那边的门打开。");}
   if(a==310&&currentRoom==18){if(chapterRanger){TellStory("队员：营门前的撤离踏板已经铺好，放心往前走。我们会沿着灯光回去。");return;}chapterRanger=true;TellStory("绞盘转动，积雪从营地门上滑落。你扶起受困队员，把撤离踏板铺到营地门前。","队员：别把冰全砸碎。我们靠它过冬，只是今年，它忘了退。");}
   if(a==311)TellStory("营地的求救灯还亮着。少年沿原路返回，去打开那道冻住的门。");
   if(a==312&&chapterStone&&currentRoom==41){if(chapterWest){JourneyHint("西侧绞盘已复位");return;}chapterWest=true;TellStory("你清开西侧闸叶，握住绞盘，把冰层下的铁链拉直。第一股细流穿过闸缝。");}
   if(a==313&&chapterStone&&currentRoom==41){if(chapterEast){JourneyHint("东侧绞盘已复位");return;}chapterEast=true;TellStory("东侧的绞盘终于转动，闸叶升起。困在殿中的潮水，第一次朝海湾流去。");}
   if(a==314&&currentRoom==41){if(!chapterStone||!chapterWest||!chapterEast||!chapterRanger){JourneyHint("先救出队员、寻回冰石，并清理两侧闸叶");return;}chapterLampCarried=true;EnterExplorationRoom(0,-1);TellStory("两股潮流在闸外汇合，浮冰缓慢移向海面。你沿队员修好的归路回到码头。","守塔人：把灯点起来吧。海上的人，该回家了。");}
   if(a==315){RoomNode n=journeyRooms[currentRoom];if(!IceRestRoom(n))return;if(!n.claimed){n.claimed=true;health=Mathf.Min(6,health+2);shield=Mathf.Min(EffectiveMaximumShield,shield+2);elementPower=Mathf.Min(ElementMaximum,elementPower+25);JourneyHint("营地整备 · 生命+2、护盾+2、元素+25");}else JourneyHint("本处物资已领取 · 清房后会自动保存");}if(a==316)ReadIceRouteRecord();
   if(a==320&&currentRoom==0&&chapterStone&&chapterWest&&chapterEast&&chapterRanger&&chapterLampCarried){chapterCg=true;storyLines=null;}
   BuildChapterActions();if(a==310)PlayWinchTurn(new Vector2(-3.8f,-.4f));if(a==312||a==313)PlayWinchTurn(new Vector2(a==312?-3:3,1));RequestCheckpoint();SaveChapterCheckpoint(false);
  }
  private void FinishIceChapterBoss(){int stage=journeyRooms[currentRoom].stage;ClearJourneyRoom();health=Mathf.Max(1,health);journeyComplete=false;if(stage==0)TellStory("裂冰甲兽收起碎裂的晶甲，退回雪雾。它身后的记录册里，留着破冰队最后的路线。","沿石阶进入冰峡前，先读读这册记录。");else if(stage==1)TellStory("冰镜碎成细小的光，巡狩者收起长牙。峡谷深处的潮汐殿露出了轮廓。","队员：潮水被困在殿里。让它流出来，港口才有归路。");else{chapterStone=true;TellStory("寒潮守望者胸前的紫纹逐段熄灭。少年托住冰元素碎片，殿下传来潮水碰撞的回声。","少年：石头找回来了，海上的冰还没退。去闸室，把水路接通。");}BuildChapterActions();UpdateExplorationDoors();RequestCheckpoint();SaveChapterCheckpoint(false);}
  private string IceChapterObjective(){if(chapterEnding)return currentRoom==0?"前往右侧码头 · F 乘船前往赤炉群岛":"返回冰港 · 右侧码头可继续前往赤炉群岛";if(currentRoom==2&&journeyRooms[2].cleared&&!iceSpikeKnown)return "读取破冰队记录 · 学习冰法术后沿石阶进入冰峡";if(chapterStone&&!chapterRanger)return "先返回受困营地救出破冰队，再完成回流总闸";if(chapterStone)return !chapterWest||!chapterEast?(currentRoom==41?"清理两侧闸叶 · 转动绞盘恢复回流":"前往回流闸室 · 清理两侧闸叶"):!chapterLampCarried?"两侧绞盘已复位 · 开启回流总闸":"返回码头 · 点亮归航灯";if(journeyRooms[currentRoom].stage==1&&!chapterRanger)return "寻找受困营地 · 转动绞盘救出破冰队";return "沿石门探索 · 清理守关者后由石阶深入";}
  private void DrawIceEnding(float w,float h){HudRect(new Rect(0,0,w,h),Color.black);if(chapterEndingArt!=null)GUI.DrawTexture(new Rect(0,0,w,h),chapterEndingArt,ScaleMode.ScaleToFit);HudRect(new Rect(0,h-145,w,145),new Color(.02f,.04f,.07f,.9f));CenterLabel(new Rect(20,h-130,w-40,40),"潮声穿过长夜",journeyTitleStyle);CenterLabel(new Rect(20,h-83,w-40,35),"冰会再结，潮也会再来。灯还亮着，就有人等你回家。",journeyTextStyle);CenterLabel(new Rect(20,h-43,w-40,30),"F / ESC 继续 · 冰元素已保存 · 南方赤色海岸的旅程仍在前方",journeySmallStyle);}
